pub fn stats(name:WeaponName,level:i32,ascend:bool)->Option<(f64,f64)>{
  if !(1..=90).contains(&level){return None;}
  let i=(level-1) as usize;
  let (atk,sub,promoted)=match name {
    WeaponName::PrizedIsshinBlade=>(&PRIZEDISSHINBLADE_ATK,&PRIZEDISSHINBLADE_SUB,&PRIZEDISSHINBLADE_ASC),
    WeaponName::AthameArtis=>(&ATHAMEARTIS_ATK,&ATHAMEARTIS_SUB,&ATHAMEARTIS_ASC),
    WeaponName::MoonweaverDawn=>(&MOONWEAVERDAWN_ATK,&MOONWEAVERDAWN_SUB,&MOONWEAVERDAWN_ASC),
    WeaponName::SerenitysCall=>(&SERENITYSCALL_ATK,&SERENITYSCALL_SUB,&SERENITYSCALL_ASC),
    WeaponName::LightbearingMoonshard=>(&LIGHTBEARINGMOONSHARD_ATK,&LIGHTBEARINGMOONSHARD_SUB,&LIGHTBEARINGMOONSHARD_ASC),
    WeaponName::WhitelakeFrostfeather=>(&WHITELAKEFROSTFEATHER_ATK,&WHITELAKEFROSTFEATHER_SUB,&WHITELAKEFROSTFEATHER_ASC),
    WeaponName::ExaiphanesBlade=>(&EXAIPHANESBLADE_ATK,&EXAIPHANESBLADE_SUB,&EXAIPHANESBLADE_ASC),
    WeaponName::AmberBead=>(&AMBERBEAD_ATK,&AMBERBEAD_SUB,&AMBERBEAD_ASC),
    WeaponName::NightweaversLookingGlass=>(&NIGHTWEAVERSLOOKINGGLASS_ATK,&NIGHTWEAVERSLOOKINGGLASS_SUB,&NIGHTWEAVERSLOOKINGGLASS_ASC),
    WeaponName::ReliquaryOfTruth=>(&RELIQUARYOFTRUTH_ATK,&RELIQUARYOFTRUTH_SUB,&RELIQUARYOFTRUTH_ASC),
    WeaponName::DawningFrost=>(&DAWNINGFROST_ATK,&DAWNINGFROST_SUB,&DAWNINGFROST_ASC),
    WeaponName::EtherlightSpindlelute=>(&ETHERLIGHTSPINDLELUTE_ATK,&ETHERLIGHTSPINDLELUTE_SUB,&ETHERLIGHTSPINDLELUTE_ASC),
    WeaponName::BlackmarrowLantern=>(&BLACKMARROWLANTERN_ATK,&BLACKMARROWLANTERN_SUB,&BLACKMARROWLANTERN_ASC),
    WeaponName::NocturnesCurtainCall=>(&NOCTURNESCURTAINCALL_ATK,&NOCTURNESCURTAINCALL_SUB,&NOCTURNESCURTAINCALL_ASC),
    WeaponName::AngelosHeptades=>(&ANGELOSHEPTADES_ATK,&ANGELOSHEPTADES_SUB,&ANGELOSHEPTADES_ASC),
    _=>return None,
  };
  let asc=if ascend {match level{20=>Some(0),40=>Some(1),50=>Some(2),60=>Some(3),70=>Some(4),80=>Some(5),_=>None}}else{None};
  Some((asc.map(|j|promoted[j]).unwrap_or(atk[i]),sub[i]))
}
